import PublishingStatus from "~/assets/data/publishing-status.json";

// Requeue a failed publish task. The dataset is still locked and its data still
// frozen, so the payload generated by finalize.post.ts is still valid and the
// task can start over. Allowed through the lock by server/middleware/datasetLock.ts
export default defineEventHandler(async (event) => {
  await datasetMinAdminPermission(event);

  const { datasetId } = event.context.params as {
    datasetId: string;
  };

  const dataset = await prisma.dataset.findUnique({
    where: {
      id: datasetId,
    },
  });

  if (!dataset || dataset.deletedAt) {
    throw createError({
      statusCode: 404,
      statusMessage: "Dataset not found",
    });
  }

  if (!dataset.lockedAt || dataset.status === "published") {
    throw createError({
      statusCode: 409,
      statusMessage: "This dataset has no publish to retry",
    });
  }

  const publishTask = await prisma.task.findFirst({
    orderBy: {
      created: "desc",
    },
    where: {
      datasetId,
      type: "publish-dataset",
    },
  });

  if (!publishTask || publishTask.status !== "failed") {
    throw createError({
      statusCode: 409,
      statusMessage: "The publish has not failed",
    });
  }

  await prisma.$transaction(async (tx) => {
    // Only requeue it if no one else has since it was read
    const { count } = await tx.task.updateMany({
      data: {
        attempts: 0,
        completedAt: null,
        error: "",
        heartbeatAt: null,
        runAfter: new Date(),
        startedAt: null,
        status: "pending",
      },
      where: {
        id: publishTask.id,
        status: "failed",
      },
    });

    if (count === 0) {
      throw createError({
        statusCode: 409,
        statusMessage: "The publish has already been retried",
      });
    }

    await tx.datasetPublishingStatus.update({
      data: {
        comment: "Queued for publishing",
        currentFileNumber: 0,
        fileCount: 0,
        status: PublishingStatus["indexing-dataset"].index,
      },
      where: {
        datasetId,
      },
    });
  });

  return {
    success: true,
  };
});
